 local r=np.std(a,{axis=1,ddof=2,dtype="float64"})
 assert(close(r,(0/0),5e-3),"stats scalar 1597")
end
do -- stats 1598 bool (0, 3)
 local a=np.reshape(np.array({},np.bool),{0,3})
 local r=np.var(a,{axis=1})
 assert(r.dtype=="float64","stats dtype 1598 "..r.dtype)
 assert(close(r:tolist(),{(0/0),(0/0),(0/0)},5e-4),"stats val 1598")
end
do -- stats 1599 uint64 (0, 3)
 local a=np.reshape(np.array({},np.uint64),{0,3})
 local r=np.std(a,{keepdims=true})
 assert(r.dtype=="float64","stats dtype 1599 "..r.dtype)
 assert(close(r:tolist(),{{(0/0)}},5e-4),"stats val 1599")
end
print('stats differential: 1600 cases passed')
